'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var uniform = require( '@stdlib/random/base/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var pdf = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( bm ) {
	var sigma;
	var len;
	var mu;
	var x;
	var a;
	var b;
	var y;
	var i;

	len = 100;
	x = new Float64Array( len );
	a = new Float64Array( len );
	b = new Float64Array( len );
	mu = new Float64Array( len );
	sigma = new Float64Array( len );

	for ( i = 0; i < len; i++ ) {
		a[ i ] = uniform( -20.0, 0.0 );
		b[ i ] = uniform( a[ i ] + 1.0, a[ i ] + 40.0 );
		mu[ i ] = uniform( a[ i ], b[ i ] );
		sigma[ i ] = uniform( 1.0, 5.0 );
		x[ i ] = uniform( a[ i ], b[ i ] );
	}

	bm.tic();
	for ( i = 0; i < bm.iterations; i++ ) {
		y = pdf( x[ i % len ], a[ i % len ], b[ i % len ], mu[ i % len ], sigma[ i % len ] );
		if ( isnan( y ) ) {
			bm.fail( 'should not return NaN' );
		}
	}
	bm.toc();
	if ( isnan( y ) ) {
		bm.fail( 'should not return NaN' );
	}
	bm.pass( 'benchmark finished' );
	bm.end();
});

bench( format( '%s::factory', pkg ), function benchmark( bm ) {
	var mypdf;
	var sigma;
	var len;
	var mu;
	var a;
	var b;
	var x;
	var y;
	var i;

	a = 0.0;
	b = 1.0;
	mu = 0.5;
	sigma = 1.0;
	len = 100;
	x = new Float64Array( len );
	mypdf = pdf.factory( a, b, mu, sigma );
	for ( i = 0; i < len; i++ ) {
		x[ i ] = uniform( -2.0, 2.0 );
	}

	bm.tic();
	for ( i = 0; i < bm.iterations; i++ ) {
		y = mypdf( x[ i % len ] );
		if ( isnan( y ) ) {
			bm.fail( 'should not return NaN' );
		}
	}
	bm.toc();
	if ( isnan( y ) ) {
		bm.fail( 'should not return NaN' );
	}
	bm.pass( 'benchmark finished' );
	bm.end();
});
